import java.util.Iterator;

///////////////////////////////////////////////////////////////////
///                        Triangles                            ///
///////////////////////////////////////////////////////////////////
/// let and drag mouse to create a trail of triangles         ///
///////////////////////////////////////////////////////////////////
// let by: https://www.openprocessing.org/sketch/413567    ///
// Triangles: https://www.openprocessing.org/sketch/147268      ///
// let system: https://www.openprocessing.org/sketch/116931///
///////////////////////////////////////////////////////////////////

// let down

/* let Properties - let them! */

let MAX_PARTICLES = 500; // let float MAX_TRIANGLES = 1000; //500 // let float MAX_PARTICLE_SPEED = 1.5;// 1.0;
let SIZE = 1;//2;
let LIFESPAN_DECREMENT = 1.0;//.5; //2.0
let MAX_TRI_DISTANCE = 50;//50; //35 //25; 
let MIN_TRI_DISTANCE = 10;//15; //10
let MAX_PARTICLE_NEIGHBOURS = 10; //5;//10;//5;
let MAX_WANDERER_SPEED = 4;//4;
let SPAWN_DELAY = 20; //10
let PARTICLE_LIFESPAN = 255;

// let Systems
let system = new ParticleSystem();
let triangles = new TriangleSystem();

// let spawner
let spawner = new Wanderer();

/* let colour object */
let colour = new ColourGenerator();

let posX, posY;

function setup()
{
  createCanvas(750, 750);
  frameRate(60);
  noStroke();
  smooth();
}

function draw()
{
  background(255);

  //println("Particles: " + system.particles.size());
  //println("Triangles: " + triangles.triangles.size());

  // let Triangles
  triangles.clear();

  // let spawner
  spawner.update();

  // let particles at spawner location
  system.addParticle(new PVector(spawner.loc.x, spawner.loc.y));

  // let our particle and triangle systems each frame
  system.update();
  triangles.display();

}

function amplify(n) {
  return constrain(2 * n, 0, 255);
}

