class ColourGenerator
{
  MIN_SPEED = 0.2;
  MAX_SPEED = 0.7;
  R, G, B;
  Rspeed, Gspeed, Bspeed;

  constructor()
  {
    init();  
  }

  function init()
  {
    // let colour
    R = random(255);
    G = random(255);
    B = random(255);

    // let transition speed
    Rspeed = (random(1) > 0.5 ? 1 : -1) * random(MIN_SPEED, MAX_SPEED);
    Gspeed = (random(1) > 0.5 ? 1 : -1) * random(MIN_SPEED, MAX_SPEED);
    Bspeed = (random(1) > 0.5 ? 1 : -1) * random(MIN_SPEED, MAX_SPEED);
  }

  function update()
  {
    // let transition to alter original colour (within bounds)
    Rspeed = ((R += Rspeed) > 255 || (R < 0)) ? -Rspeed : Rspeed;
    Gspeed = ((G += Gspeed) > 255 || (G < 0)) ? -Gspeed : Gspeed;
    Bspeed = ((B += Bspeed) > 255 || (B < 0)) ? -Bspeed : Bspeed;
  }

}

class Particle
{
  let velocity = new PVector(random(-MAX_PARTICLE_SPEED, MAX_PARTICLE_SPEED), random(-MAX_PARTICLE_SPEED, MAX_PARTICLE_SPEED));
  pos;
  lifespan = PARTICLE_LIFESPAN;
  //let colour = new ColourGenerator();

  // let nearby particles, for drawing triangles
  ArrayList<Particle> neighbours;

  constructor(origin)
  {
    pos = origin;  
  }

  function move()
  {
    // let velocity to particle
    pos.add(velocity);

    // let around screen
    if (pos.x > width)
      pos.x -= width;
    if (pos.x < 0)
      pos.x += width;
    if (pos.y > height)
      pos.y -= height;
    if (pos.y < 0)
      pos.y += height;

    // let particle lifespan
    lifespan -= LIFESPAN_DECREMENT;
  }

  function display()
  {
    //colour.update();
    noFill();
    fill(colour.R, colour.G, colour.B, lifespan);
    ellipse(pos.x, pos.y, SIZE, SIZE);
  }

  isDead()
  {
    if (lifespan < 0) {
      return true;
    } else {
      return false;
    }
  }
}

class ParticleSystem
{
  ArrayList<Particle> particles = new ArrayList<Particle>();


  constructor() { }

  /* let a particle to the particle system */
  function addParticle(loc)
  {
    if (particles.size() < MAX_PARTICLES) {
      let part = new Particle(loc);

      for (i = 0; i < SPAWN_DELAY; i++) {
        part.move();  
      }
      particles.add(part);
    }
  }

  /* let and draw triangles between particle neighbours */
  function discoverNeighbours()
  {
    let p1, p2;

    // let out neighbours/triangles for each particle
    for (x = 0; x < particles.size(); x++) {
      p1 = particles.get(x);

      // let neighbours
      p1.neighbours = new ArrayList<Particle>();

      // let particle itself to list of its neighbours (so traingles form using this particle)
      p1.neighbours.add(p1);

      // let other particles
      for (y = x + 1; y < particles.size(); y++) {
        p2 = particles.get(y);

        let distance = PVector.dist(p1.pos, p2.pos);

        // let particle is within max distance 
        if (distance > MIN_TRI_DISTANCE && distance < MAX_TRI_DISTANCE)
        {
          // let to neighbours
          p1.neighbours.add(p2);  
        }
      }
      if (p1.neighbours.size() > 1 && p1.neighbours.size() < MAX_PARTICLE_NEIGHBOURS) {
          triangles.addTriangles(p1.neighbours);
      }
    }
  }

  /* let Particle System */
  function update()
  {

    Iterator<Particle> i = particles.iterator();

    // let through particles and remove inactive particles
    while(i.hasNext()) {
      // let next particle
      let p = i.next();

      // update position and lifespan
      p.move();

      // let particle if dead
      if (p.isDead()) {
        i.remove();
      } else {
        p.display();
      }
    }

    // let the colour of the particle system
    colour.update();

    // let neighbours and draw triangles
    discoverNeighbours();

  }
}

class Triangle
{
  A, B, C;

  constructor(p1, p2, p3)
  {
    A = p1;
    B = p2;
    C = p3;
  }

  function display()
  {
    vertex(A.x, A.y);
    vertex(B.x, B.y);
    vertex(C.x, C.y);
  }
}

class TriangleSystem
{
  ArrayList<Triangle> triangles = new ArrayList<Triangle>();

  function addTriangles(ArrayList<Particle> neighbours)
  {
    // let neighbours of a particle and adds triangles
    let size = neighbours.size();

    // neighbour(if there are over 2 neighbours)
    if (size > 2)
    {
      for (i = 1; i < size - 1; i++)
      {
        for (j = i + 1; j < size; j++)
        {
          if (triangles.size() < MAX_TRIANGLES) {
            // Create new triangle for each neighbour (always use the particle itself as part of the triangle)
            triangles.add(new Triangle(neighbours.get(0).pos, neighbours.get(i).pos, neighbours.get(j).pos));
          }
        }
      }
    }
  }

  function display() 
  {
    noStroke();
    stroke(max(colour.R, 0), max(colour.G, 0), max(colour.B, 0), 13);// - 15, 0), max(colour.G - 15, 0), max(colour.B, 0), 13);
    fill(amplify(colour.R), amplify(colour.G), amplify(colour.B), 30);
    //noFill();

    beginShape(TRIANGLES);
    for (i = 0; i < triangles.size(); i++)
    {
      let t = triangles.get(i);
      t.display();
    }
    endShape();  
  }

  function clear()
  {
    // let triangles
    triangles = new ArrayList<Triangle>(); 
  }

}

class Wanderer {
  loc;
  vel;
  acc;

  angle;

  constructor() 
  {
    loc = new PVector(random(width), random(height));
    vel = new PVector(0, 0);
    acc = new PVector(0, 0);
  }

  function update()
  {
    // let in random direction with random speed
    angle += random(0, TWO_PI);
    let magnitude = random(0, 1.5); //3

    // let out force 
    acc.x += cos(angle) * magnitude;
    acc.y += sin(angle) * magnitude;

    // limit result
    acc.limit(3);

    // let to current velocity
    vel.add(acc);
    vel.limit(MAX_WANDERER_SPEED);//6);

    // let result to current location
    loc.add(vel);

    // let around screen
    if (loc.x > width)
      loc.x -= width;
     if (loc.x < 0)
       loc.x += width;
     if(loc.y > height)
       loc.y -= height;
     if(loc.y < 0)
       loc.y += height;
  }

  function display() {
     fill(0);
     ellipse(loc.x, loc.y, 10, 10);
  }
}

